pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a mock ERC721 token for testing
        // We'll use a simple inline ERC721-like contract that c can interact with
        MockERC721 nft = new MockERC721();
        uint256 tokenId = 1;
        nft.mint(address(c), tokenId);

        // Initialize the pool with non-zero virtual reserves so it is operational
        c.initialize(address(0), address(nft), 100e18, 1e18, 0, 100, bytes32(0), false, false);

        // Now the contract owns tokenId 1 of the mock NFT
        // Call flashLoan with this contract as receiver; onERC721Received will return wrong value in mutant
        bool success;
        try c.flashLoan(IERC3156FlashBorrower(address(this)), address(nft), tokenId, "") {
            success = true;
        } catch {
            success = false;
        }

        // In the reference, onERC721Received returns the correct selector, so flashLoan succeeds.
        // In the mutant, onERC721Received returns 0x00000000, causing safeTransferFrom to revert, so flashLoan fails.
        // We assert success == true, which holds for reference and fails for mutant.
        assertTrue(success);
    }
}

contract MockERC721 {
    mapping(uint256 => address) public _ownerOf;
    mapping(address => uint256) public _balanceOf;

    function mint(address to, uint256 id) public {
        _ownerOf[id] = to;
        _balanceOf[to]++;
    }

    function ownerOf(uint256 id) public view returns (address) {
        return _ownerOf[id];
    }

    function safeTransferFrom(address from, address to, uint256 id) public {
        require(_ownerOf[id] == from, "wrong from");
        _ownerOf[id] = to;
        _balanceOf[from]--;
        _balanceOf[to]++;
        // Check receiver's onERC721Received
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, id, "") returns (bytes4 selector) {
                require(selector == IERC721Receiver.onERC721Received.selector, "unsafe");
            } catch {
                revert("invalid receiver");
            }
        }
    }

    function transferFrom(address from, address to, uint256 id) public {}

    function balanceOf(address owner) public view returns (uint256) { return _balanceOf[owner]; }
}

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

interface IERC3156FlashBorrower {
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external returns (bytes32);
}

contract IERC3156FlashBorrower is IERC3156FlashBorrower {
    function onFlashLoan(address, address, uint256, uint256, bytes calldata) external returns (bytes32) {
        return keccak256("onFlashLoan");
    }
}

